<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff;--card:#ffffff;--muted:#666;--accent:#2f6b4e;--warm:#f6f9f6}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,#fbfdfa,#f6fbf8)}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#7fbf9e);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none}
    .cta{background:var(--accent);color:#fff;padding:9px 12px;border-radius:9px;text-decoration:none}
    main{max-width:1080px;margin:14px auto;padding:18px}
