    .small{font-size:13px;color:var(--muted)}
    footer{margin-top:20px;text-align:center;color:var(--muted)}
  </style>
</head>
<body>
  <header>
    <div style='display:flex;gap:12px;align-items:center'>
      <div class='logo'>W</div>
      <div>
        <div style='font-weight:700'>{{BUSINESS_NAME}}</div>
        <div style='font-size:12px;color:var(--muted)'>Practical routines, quietly effective</div>
      </div>
    </div>
    <nav>
      <a href='index.html'>Home</a>
      <a href='about.html'>Method</a>
      <a href='services.html'>Offerings</a>
      <a href='programs.html'>Tracks</a>
      <a href='book.html'>Reserve</a>
      <a class='cta' href='{{PRIMARY_CTA_URL}}'>{{PRIMARY_CTA_LABEL}}</a>
    </nav>
  </header>

  <main>
    <div class='grid'>
      <section>
        <h2 style='margin:0 0 8px 0'>Offerings designed for steady progress</h2>
        <p class='small' style='margin:0 0 18px 0;color:var(--muted)'>Each option is framed around habits, short experiments, and repeatable review checkpoints. Choose what fits your calendar and inclination.</p>

        <div class='cards'>
          <article class='service'>
            <div class='label'>Daily Lab</div>
            <div class='title'>Micro-rituals membership</div>
            <p class='desc'>A rolling membership that supplies a weekly micro-ritual, short coaching notes, and a monthly group check-in. Emphasis on small actions you can maintain.</p>
            <div class='price'>From $28/month</div>
            <div class='muted'>No long homework, monthly cancelation</div>
            <a class='try' href='#' id='tryMembership'>Try a sample practice</a>
          </article>

          <article class='service'>
            <div class='label'>Focused Track</div>
            <div class='title'>Three-week reset</div>
            <p class='desc'>A short guided track with daily, five-minute tasks and a weekly reflection to cement a new habit pattern.</p>
            <div class='price'>One payment of $149</div>
            <div class='muted'>Includes downloadable checklist and journal prompts</div>
            <a class='try' href='book.html'>Enroll</a>
          </article>

          <article class='service'>
            <div class='label'>Group</div>
            <div class='title'>Anchor circle</div>
            <p class='desc'>A small cohort meeting weekly to share experiments, troubleshoot barriers, and refine a personal framework.</p>
            <div class='price'>Cohort rate, contact for details</div>
            <div class='muted'>Limited seats for focused attention</div>
            <a class='try' href='contact.html'>Request details</a>
          </article>

          <article class='service'>
            <div class='label'>Short session</div>
            <div class='title'>Momentum consult</div>
            <p class='desc'>A single 45-minute session to identify one high-leverage habit and a step-by-step plan to test it for a week.</p>
            <div class='price'>$89 / session</div>
            <div class='muted'>Actionable, minimal follow-up required</div>
            <a class='try' href='book.html'>Schedule</a>
          </article>
        </div>
      </section>

      <aside>
        <div style='font-weight:700'>Try a practice</div>
        <p class='small'>Open a guided breathing, journaling, or intention-setting demo. No sign-up required — 2 to 5 minutes.</p>
        <a class='try' href='#' id='openPracticeSidebar'>Try it now</a>

        <hr style='margin:14px 0;border:none;border-top:1px dashed #e9f1ea'>
        <div style='font-weight:700'>Membership framing</div>
        <p class='small' style='margin:8px 0 0 0;color:var(--muted)'>We frame pricing as support for steady habit testing: a modest recurring investment to keep small steps consistent.</p>
      </aside>
    </div>

    <footer>
      <div style='color:var(--muted)'>Contact: {{EMAIL}} • {{PHONE}} • Serving {{CITY}}, {{STATE}}</div>
    </footer>
  </main>

  <!-- Reuse the modal from other pages via local script -->
  <div id='svcOverlay' style='display:none;position:fixed;inset:0;background:rgba(10,12,10,0.5);align-items:center;justify-content:center'>
    <div style='background:#fff;border-radius:12px;padding:18px;max-width:640px;margin:20px auto'>
      <div style='display:flex;justify-content:space-between;align-items:center'>
        <strong>Quick guided practice</strong>
        <button id='svcClose' style='background:none;border:0;font-size:18px'>✕</button>
      </div>
      <div style='margin-top:12px'>
        <p style='margin:0 0 10px 0;color:var(--muted)'>Choose a short exercise and follow the on-screen cues.</p>
        <div style='display:flex;gap:8px'>
          <button class='try' data-kind='breath'>Breathing</button>
          <button class='try' data-kind='journ'>Journaling</button>
          <button class='try' data-kind='intent'>Intention</button>
        </div>
        <div id='svcPrompt' style='margin-top:12px;color:var(--muted)'></div>
        <div style='display:flex;gap:8px;margin-top:12px'>
          <button id='svcStart' class='cta' style='background:var(--accent)'>Start</button>
          <button id='svcStop' class='try' disabled>Stop</button>
        </div>
      </div>
    </div>
  </div>

  <script>
    // Small modal handler for services page
    (function(){
      var overlay = document.getElementById('svcOverlay');
      var openButtons = document.querySelectorAll('#openPracticeSidebar,#tryMembership');
      var closeBtn = document.getElementById('svcClose');
      var prompt = document.getElementById('svcPrompt');
      var start = document.getElementById('svcStart');
      var stop = document.getElementById('svcStop');
      var kind = 'breath';

      openButtons.forEach(function(b){b.addEventListener('click',function(e){e.preventDefault(); overlay.style.display='flex'; prompt.textContent='Selected: breathing demo.'; kind='breath';});});
      document.querySelectorAll('[data-kind]').forEach(function(b){b.addEventListener('click',function(){kind=b.getAttribute('data-kind'); prompt.textContent = {breath:'Breathing: 4-4-6 cycle',journ:'Write freely for 3 minutes',intent:'Craft a one-line intention'}[kind];});});
